// Copies the compiled contracts into web/bytecode.js so the web page's
// "Deploy" button can deploy them through MetaMask.
// Run with:  npm run export   (after changing a contract)
const fs = require("fs");
const path = require("path");
const read = (name) => require(path.join(__dirname, `../artifacts/contracts/${name}.sol/${name}.json`)).bytecode;

const out = { gifts: read("GiftAStock"), stock: read("MockStock") };
fs.writeFileSync(
  path.join(__dirname, "../web/bytecode.js"),
  "// Auto-generated by scripts/export-bytecode.js. Do not edit by hand.\nwindow.BYTECODE = " + JSON.stringify(out) + ";\n"
);
console.log("Wrote web/bytecode.js");
